create table users (id uuid primary key, email varchar(320) not null unique, password_hash varchar(100) not null, status varchar(20) not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null);
create table emergency_profiles (id uuid primary key, owner_user_id uuid not null unique references users(id), display_name varchar(200) not null, date_of_birth date, blood_group varchar(8), critical_instructions varchar(4000), status varchar(20) not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null);
create table emergency_contacts (id uuid primary key, profile_id uuid not null references emergency_profiles(id), name varchar(200) not null, relationship varchar(100), phone_number varchar(32) not null, display_order integer not null, active boolean not null default true, unique(profile_id, display_order));
create table profile_allergies (id uuid primary key, profile_id uuid not null references emergency_profiles(id), label varchar(500) not null, display_order integer not null);
create table profile_conditions (id uuid primary key, profile_id uuid not null references emergency_profiles(id), label varchar(500) not null, display_order integer not null);
create table profile_medications (id uuid primary key, profile_id uuid not null references emergency_profiles(id), label varchar(500) not null, dose_instruction varchar(500), display_order integer not null);
create table qr_credentials (id uuid primary key, profile_id uuid not null references emergency_profiles(id), token_verifier varchar(100) not null unique, status varchar(20) not null, issued_at timestamp with time zone not null, revoked_at timestamp with time zone, expires_at timestamp with time zone, last_used_at timestamp with time zone);
create table emergency_sessions (id uuid primary key, handle_verifier varchar(100) not null unique, qr_credential_id uuid not null references qr_credentials(id), profile_id uuid not null references emergency_profiles(id), issued_at timestamp with time zone not null, expires_at timestamp with time zone not null, revoked_at timestamp with time zone, request_fingerprint varchar(128));
create table medical_documents (id uuid primary key, profile_id uuid not null references emergency_profiles(id), storage_reference varchar(512) not null unique, document_name varchar(255) not null, document_type varchar(100) not null, access_policy varchar(30) not null, processing_status varchar(30) not null, lifecycle_status varchar(30) not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null);
create table document_access_requests (id uuid primary key, document_id uuid not null references medical_documents(id), emergency_session_id uuid not null references emergency_sessions(id), emergency_contact_id uuid not null references emergency_contacts(id), status varchar(30) not null, created_at timestamp with time zone not null, expires_at timestamp with time zone not null, completed_at timestamp with time zone);
create table emergency_contact_otp_challenges (id uuid primary key, access_request_id uuid not null references document_access_requests(id), emergency_contact_id uuid not null references emergency_contacts(id), otp_verifier varchar(100) not null, expires_at timestamp with time zone not null, attempt_count integer not null, max_attempts integer not null, consumed_at timestamp with time zone, created_at timestamp with time zone not null);
create table temporary_document_authorizations (id uuid primary key, document_id uuid not null references medical_documents(id), emergency_session_id uuid not null references emergency_sessions(id), access_request_id uuid not null unique references document_access_requests(id), authorized_contact_id uuid not null references emergency_contacts(id), issued_at timestamp with time zone not null, expires_at timestamp with time zone not null, revoked_at timestamp with time zone);
create table audit_events (id uuid primary key, event_type varchar(100) not null, outcome varchar(20) not null, actor_user_id uuid, profile_id uuid, qr_credential_id uuid, emergency_session_id uuid, medical_document_id uuid, document_access_request_id uuid, temporary_document_authorization_id uuid, correlation_id varchar(100) not null, metadata varchar(2000), occurred_at timestamp with time zone not null);
create index idx_sessions_handle on emergency_sessions(handle_verifier);
create index idx_documents_profile on medical_documents(profile_id);
create index idx_requests_session_document on document_access_requests(emergency_session_id, document_id);
